 *
 *      insales.removeOptionValue({
 *        token: '1234567890',
 *        url: 'shop-test.myinsales.ru',
 *        optionnameid: '1',
 *        optionvalueid: '20'
 *      }).then(response => {
 *        console.info(response.data);
